#pragma once

/* Base version of the Wamphyre Autoloader (WAMP) content.
 * Bump this when the autoloader frontend changes — it triggers the app-cache
 * update and also marks the matching WAMPI installer build. */
#define WAMP_VERSION "0.6.1"

/* Full build version (stable: <base>, dev: <base>-<hash|timestamp>),
 * generated by tools/gen_version.py — see include/wampi_version.h */
#include "wampi_version.h"

/* Network Settings — arbitrary port, chosen to avoid colliding with other
 * homebrew HTTP servers (must match the deeplink in assets/param.json.template) */
#define WAMPI_PORT 18181

/* Title ID of the installed homescreen app ("Wamphyre Autoloader").
 * The fork's own ID; the legacy upstream app (WKAL00001) is uninstalled
 * automatically after a successful install — see src/http_server.c. */
#define WAMP_TITLE_ID "WAMP00001"

/* Title ID of the legacy upstream app, removed on install when present. */
#define WAMP_LEGACY_TITLE_ID "WKAL00001"

/* Process identity — used to kill stale installer instances on startup.
 * The legacy upstream name is killed too, so an old installer cannot hold
 * the port while the new one starts. */
#define WAMPI_THREAD_NAME "wampi.elf"
#define WAMP_LEGACY_THREAD_NAME "wkali.elf"

/* Routes */
#define ROUTE_INDEX "/"
#define ROUTE_INDEX_HTML "/index.html"
#define ROUTE_CACHE_MANIFEST "/cache.appcache"
#define ROUTE_INSTALL "/install"
#define ROUTE_VERSION "/version"
#define ROUTE_CLEAR_WEBKIT_DATA "/clear-webkit-data"
#define ROUTE_EXIT "/exit"

/* Native platform helpers are owned by remote-loader. */
#include "installer_support.h"
